import re
from datetime import datetime, timedelta, date, time
from pathlib import Path

BASE = Path('/app')

def parse_dt(s):
    return datetime.strptime(s, '%Y%m%dT%H%M%SZ')

def parse_calendar(path):
    text = path.read_text(encoding='utf-8')
    events = []
    for m in re.finditer(r'BEGIN:VEVENT\s*(.*?)\s*END:VEVENT', text, re.S):
        block = m.group(1)
        sm = re.search(r'^DTSTART[^:]*:(\d{8}T\d{6}Z)\s*$', block, re.M)
        em = re.search(r'^DTEND[^:]*:(\d{8}T\d{6}Z)\s*$', block, re.M)
        summ = re.search(r'^SUMMARY:(.*)$', block, re.M)
        if not sm or not em:
            continue
        events.append({
            'start': parse_dt(sm.group(1)),
            'end': parse_dt(em.group(1)),
            'summary': summ.group(1).strip() if summ else '',
        })
    return events

calendars = {p: parse_calendar(BASE / f'{p}_calendar.ics') for p in ('alice', 'bob', 'carol')}

def overlaps(a0, a1, b0, b1):
    return a0 < b1 and b0 < a1

extra_carol = []
for ev in calendars['carol']:
    if ev['end'].time() >= time(16, 45):
        extra_carol.append((ev['end'], ev['end'] + timedelta(minutes=15)))

def valid(person, start, end):
    d = start.date()
    if end - start != timedelta(hours=1):
        return False
    if person == 'alice':
        if start.time() < time(9) or end.time() > time(14):
            return False
    elif person == 'bob':
        if start.time() < time(10):
            return False
        if d.weekday() in (1, 3) and end.time() > time(16, 30):
            return False
    elif person == 'carol':
        if start.time() < time(9) or end.time() > time(17):
            return False
        lunch0 = datetime.combine(d, time(12, 0))
        lunch1 = datetime.combine(d, time(12, 30))
        if overlaps(start, end, lunch0, lunch1):
            return False
    for ev in calendars[person]:
        if overlaps(start, end, ev['start'], ev['end']):
            return False
    if person == 'carol':
        for b0, b1 in extra_carol:
            if overlaps(start, end, b0, b1):
                return False
    return True

def all_valid(start, end):
    return all(valid(p, start, end) for p in ('alice', 'bob', 'carol'))

days = [date(2024, 1, 15) + timedelta(days=i) for i in range(5)]
valid_slots = []
for d in days:
    t = datetime.combine(d, time(9, 0))
    limit = datetime.combine(d, time(18, 0))
    while t + timedelta(hours=1) <= limit:
        e = t + timedelta(hours=1)
        if all_valid(t, e):
            valid_slots.append((t, e))
        t += timedelta(minutes=1)

print('valid slot count:', len(valid_slots))
for s, e in valid_slots[:10]:
    print(' valid:', s.strftime('%a %Y-%m-%d %H:%M'), '-', e.strftime('%H:%M'))
assert valid_slots, 'No valid slots found'

non_monday = [x for x in valid_slots if x[0].weekday() != 0]
pref1 = non_monday if non_monday else valid_slots
morning = [x for x in pref1 if x[0].time() >= time(9) and x[1].time() <= time(12)]
pref2 = morning if morning else pref1
expected = min(pref2, key=lambda x: x[0])
print('expected preferred-earliest:', expected[0].strftime('%a %Y-%m-%d %H:%M'), '-', expected[1].strftime('%H:%M'))

out_path = BASE / 'meeting_scheduled.ics'
assert out_path.is_file() and out_path.stat().st_size > 0
text = out_path.read_text(encoding='utf-8')
assert text.startswith('BEGIN:VCALENDAR')
assert text.rstrip().endswith('END:VCALENDAR')
normalized = text.replace('\r\n', '\n')
assert '\nVERSION:2.0\n' in normalized
assert '\nPRODID:' in normalized
blocks = re.findall(r'BEGIN:VEVENT\s*(.*?)\s*END:VEVENT', text, re.S)
assert len(blocks) == 1, f'expected 1 VEVENT, got {len(blocks)}'
b = blocks[0]

def prop(name):
    m = re.search(rf'^{name}[^:]*:(.*)$', b, re.M)
    return m.group(1).strip() if m else None

assert prop('SUMMARY') == 'Team Planning Meeting'
start_s, end_s = prop('DTSTART'), prop('DTEND')
assert re.fullmatch(r'\d{8}T\d{6}Z', start_s or '')
assert re.fullmatch(r'\d{8}T\d{6}Z', end_s or '')
start, end = parse_dt(start_s), parse_dt(end_s)
attendees = set(re.findall(r'^ATTENDEE:mailto:([^\s]+)', b, re.M))
expected_attendees = {'alice@example.com', 'bob@example.com', 'carol@example.com'}
assert attendees == expected_attendees, (attendees, expected_attendees)
assert (start, end) == expected, ((start, end), expected)
assert all_valid(start, end), 'output slot violates constraints'
print('OUTPUT OK:', start_s, end_s, sorted(attendees))
print('ALL CHECKS PASSED')
